code.js:
document.querySelectorAll('.tp').forEach(box => {
  const [hour, minute] = box.querySelectorAll('input');
  const spec = [[hour, 1, 12], [minute, 0, 59]];
  spec.forEach(([input, min, max]) => {
    const fix = () => {
      let n = parseInt(input.value, 10); if (isNaN(n)) n = min;
      input.value = String(Math.min(max, Math.max(min, n))).padStart(2, '0');
    };
    input.addEventListener('input', () => { input.value = input.value.replace(/\D/g, '').slice(0, 2); });
    input.addEventListener('blur', fix);
    input.addEventListener('keydown', e => {
      if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
      e.preventDefault(); let n = parseInt(input.value, 10); if (isNaN(n)) n = min;
      n += e.key === 'ArrowUp' ? 1 : -1; if (n > max) n = min; if (n < min) n = max;
      input.value = String(n).padStart(2, '0');
    });
  });
});
